import type { WPTour } from './wordpress/types';
import { absolutePublicUrl, normalizePublicPath, plainText } from './seo.ts';

export interface Alternate { lang: string; href: string }

// These paired pages are generated by the same source template in both languages.
const pairedPages = new Set(['', '/book', '/tours', '/tours/featured', '/about-us', '/contact', '/faq', '/private-transfers', '/reviews', '/visa', '/privacy-policy', '/terms']);

export function pageAlternates(path: string, origin: string, base: string): Alternate[] {
    const prefix = base === '/' ? '' : base.replace(/\/$/, '');
    let relative = normalizePublicPath(path);
    if (prefix && (relative === prefix || relative.startsWith(prefix + '/'))) relative = relative.slice(prefix.length);
    if (relative === '/zh' || relative.startsWith('/zh/')) relative = relative.slice(3);
    if (relative === '/') relative = '';
    if (!pairedPages.has(relative)) return [];
    const en = absolutePublicUrl(origin, prefix + relative || '/') + (prefix && !relative ? '/' : '');
    const zh = absolutePublicUrl(origin, prefix + '/zh' + relative);
    return [{ lang: 'en', href: en }, { lang: 'zh', href: zh }, { lang: 'x-default', href: en }];
}

export function confirmedTourAlternates(tour: WPTour, lang: 'en' | 'zh', tours: Record<'en' | 'zh', WPTour[]>, origin: string, base: string): Alternate[] {
    const other = lang === 'en' ? 'zh' : 'en';
    const candidate = tour.translations?.[other];
    const counterpart = candidate && tours[other].find(t => t.id === candidate.id && decodeURIComponent(t.slug) === decodeURIComponent(candidate.slug));
    const back = counterpart?.translations?.[lang];
    if (!counterpart || !back || back.id !== tour.id || decodeURIComponent(back.slug) !== decodeURIComponent(tour.slug)) return [];
    const enTour = lang === 'en' ? tour : counterpart;
    const zhTour = lang === 'zh' ? tour : counterpart;
    const prefix = base === '/' ? '' : base.replace(/\/$/, '');
    const en = absolutePublicUrl(origin, `${prefix}/tours/${enTour.slug}`);
    const zh = absolutePublicUrl(origin, `${prefix}/zh/tours/${zhTour.slug}`);
    return [{ lang: 'en', href: en }, { lang: 'zh', href: zh }, { lang: 'x-default', href: en }];
}

export function tourStructuredData(tour: WPTour, origin: string, base: string, lang: 'en' | 'zh') {
    const prefix = base === '/' ? '' : base.replace(/\/$/, '');
    const locale = lang === 'zh' ? `${prefix}/zh` : prefix;
    const canonical = absolutePublicUrl(origin, `${locale}/tours/${tour.slug}`);
    return [
        { '@context': 'https://schema.org', '@type': 'TouristTrip', '@id': canonical + '#trip', name: plainText(tour.title.rendered), url: canonical, provider: { '@id': origin + '/#organization' } },
        { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [
            { '@type': 'ListItem', position: 1, name: lang === 'zh' ? '首頁' : 'Home', item: absolutePublicUrl(origin, locale || '/') + (locale === prefix && prefix ? '/' : '') },
            { '@type': 'ListItem', position: 2, name: lang === 'zh' ? '行程' : 'Tours', item: absolutePublicUrl(origin, `${locale}/tours`) },
            { '@type': 'ListItem', position: 3, name: plainText(tour.title.rendered), item: canonical },
        ] },
    ];
}
